#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long u64;
const u64 BASE = 1000000000;  // little-endian limbs of 9 decimal digits

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<u64> freq(100001);
    for (int i = 0; i < n; i++) {
        int v;
        cin >> v;
        freq[v]++;
    }
    // ending = number of good subsequences whose maximum is the current value: f[v] * (1 + ending[v-1]).
    vector<u64> ending, answer;
    for (int v = 1; v <= 100000; v++) {
        u64 count = freq[v];
        if (count == 0) {
            ending.clear();
            continue;
        }
        u64 carry = 1;  // ending + 1
        for (size_t i = 0; i < ending.size() && carry; i++) {
            ending[i] += carry;
            carry = ending[i] / BASE;
            ending[i] %= BASE;
        }
        if (carry) ending.push_back(carry);
        carry = 0;  // ending * count
        for (auto &limb : ending) {
            u64 cur = limb * count + carry;
            limb = cur % BASE;
            carry = cur / BASE;
        }
        while (carry) ending.push_back(carry % BASE), carry /= BASE;
        if (answer.size() < ending.size()) answer.resize(ending.size());
        carry = 0;  // answer += ending
        for (size_t i = 0; i < answer.size(); i++) {
            u64 cur = answer[i] + (i < ending.size() ? ending[i] : 0) + carry;
            answer[i] = cur % BASE;
            carry = cur / BASE;
            if (!carry && i >= ending.size()) break;
        }
        if (carry) answer.push_back(carry);
    }
    if (answer.empty()) {
        cout << 0 << "\n";
        return 0;
    }
    string out = to_string(answer.back());
    char buf[16];
    for (int i = (int)answer.size() - 2; i >= 0; i--) {
        snprintf(buf, sizeof buf, "%09llu", answer[i]);
        out += buf;
    }
    cout << out << "\n";
}

import java.io.*;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        int[] freq = new int[100001];
        for (int i = 0; i < n; i++) {
            st.nextToken();
            freq[(int) st.nval]++;
        }
        // ending = number of good subsequences whose maximum is the current value: f[v] * (1 + ending[v-1]).
        BigInteger ending = BigInteger.ZERO, answer = BigInteger.ZERO;
        for (int v = 1; v <= 100000; v++) {
            if (freq[v] == 0) {
                ending = BigInteger.ZERO;
                continue;
            }
            ending = ending.add(BigInteger.ONE).multiply(BigInteger.valueOf(freq[v]));
            answer = answer.add(ending);
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"math/big"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	freq := make([]int64, 100001)
	for i := 0; i < n; i++ {
		freq[nextInt()]++
	}
	// ending = number of good subsequences whose maximum is the current value: f[v] * (1 + ending[v-1]).
	ending, answer, one, count := new(big.Int), new(big.Int), big.NewInt(1), new(big.Int)
	for v := 1; v <= 100000; v++ {
		if freq[v] == 0 {
			ending.SetInt64(0)
			continue
		}
		ending.Add(ending, one)
		ending.Mul(ending, count.SetInt64(freq[v]))
		answer.Add(answer, ending)
	}
	os.Stdout.WriteString(answer.String() + "\n")
}
